window.ScripturaLexicons.BDAG_PART_0160 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zoion-bdag\" data-source=\"BDAG\" data-search=\"ζῷον, ου, τό substantivo neutro animal; ser vivente; criatura viva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζῷον, ου, τό</td><td>substantivo neutro</td><td>animal; ser vivente; criatura viva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zoopoieo-bdag\" data-source=\"BDAG\" data-search=\"ζωοποιέω verbo vivificar; dar vida; conservar vivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ζωοποιέω</td><td>verbo</td><td>vivificar; dar vida; conservar vivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zosimos-bdag\" data-source=\"BDAG\" data-search=\"Ζώσιμος, ου, ὁ nome próprio masculino Zósimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζώσιμος, ου, ὁ</td><td>nome próprio masculino</td><td>Zósimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-zotion-bdag\" data-source=\"BDAG\" data-search=\"Ζωτίων, ωνος, ὁ nome próprio masculino Zótion BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ζωτίων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Zótion</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eta-numeral-bdag\" data-source=\"BDAG\" data-search=\"η´ sinal numérico grego oito; oitavo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">η´</td><td>sinal numérico grego</td><td>oito; oitavo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-e-disjunctive-bdag\" data-source=\"BDAG\" data-search=\"ἤ partícula disjuntiva e comparativa ou; nem; do que; antes que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἤ</td><td>partícula disjuntiva e comparativa</td><td>ou; nem; do que; antes que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-e-affirmative-bdag\" data-source=\"BDAG\" data-search=\"ἦ advérbio verdadeiramente; de fato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἦ</td><td>advérbio</td><td>verdadeiramente; de fato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-egagon-bdag\" data-source=\"BDAG\" data-search=\"ἤγαγον forma verbal remissiva ver ἄγω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἤγαγον</td><td>forma verbal remissiva</td><td>ver ἄγω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hegemoneuo-bdag\" data-source=\"BDAG\" data-search=\"ἡγεμονεύω verbo governar; comandar; exercer autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡγεμονεύω</td><td>verbo</td><td>governar; comandar; exercer autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hegemonia-bdag\" data-source=\"BDAG\" data-search=\"ἡγεμονία, ας, ἡ substantivo feminino governo; chefia; direção; administração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡγεμονία, ας, ἡ</td><td>substantivo feminino</td><td>governo; chefia; direção; administração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hegemonikos-bdag\" data-source=\"BDAG\" data-search=\"ἡγεμονικός, ή, όν adjetivo dirigente; orientador; condutor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡγεμονικός, ή, όν</td><td>adjetivo</td><td>dirigente; orientador; condutor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hegemon-bdag\" data-source=\"BDAG\" data-search=\"ἡγεμών, όνος, ὁ substantivo masculino governante; dirigente; governador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡγεμών, όνος, ὁ</td><td>substantivo masculino</td><td>governante; dirigente; governador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hegeomai-bdag\" data-source=\"BDAG\" data-search=\"ἡγέομαι verbo depoente liderar; dirigir; considerar; estimar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡγέομαι</td><td>verbo depoente</td><td>liderar; dirigir; considerar; estimar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-edein-bdag\" data-source=\"BDAG\" data-search=\"ᾔδειν forma verbal remissiva ver οἶδα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ᾔδειν</td><td>forma verbal remissiva</td><td>ver οἶδα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hedeos-bdag\" data-source=\"BDAG\" data-search=\"ἡδέως advérbio com prazer; de bom grado; mais prazerosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡδέως</td><td>advérbio</td><td>com prazer; de bom grado; mais prazerosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ede-bdag\" data-source=\"BDAG\" data-search=\"ἤδη advérbio já; agora; por fim; de fato BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἤδη</td><td>advérbio</td><td>já; agora; por fim; de fato</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hedion-bdag\" data-source=\"BDAG\" data-search=\"ἥδιον, ἥδιστα formas comparativa e superlativa remissivas ver ἡδέως BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἥδιον, ἥδιστα</td><td>formas comparativa e superlativa remissivas</td><td>ver ἡδέως</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hedomai-bdag\" data-source=\"BDAG\" data-search=\"ἥδομαι verbo depoente agradar-se; deleitar-se com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἥδομαι</td><td>verbo depoente</td><td>agradar-se; deleitar-se com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hedone-bdag\" data-source=\"BDAG\" data-search=\"ἡδονή, ῆς, ἡ substantivo feminino prazer; deleite; desejo; sabor agradável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡδονή, ῆς, ἡ</td><td>substantivo feminino</td><td>prazer; deleite; desejo; sabor agradável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heduosmon-bdag\" data-source=\"BDAG\" data-search=\"ἡδύοσμον, ου, τό substantivo neutro hortelã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἡδύοσμον, ου, τό</td><td>substantivo neutro</td><td>hortelã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-zoion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζῷον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Também <span class=\"greek\">ζῶον</span>; sobre a grafia, B-D-F §26; Mlt-H. §36; L-S-J-M, s.v.; cf. Rob. 194s.; pré-socráticos, Heródoto e outros.</p><p class=\"entry-text\">① <strong>Ser vivo selvagem ou domesticado, excluídas as plantas; animal</strong>; em nossa literatura, exclui seres humanos (Diodoro Sículo 3, 31, 2; 5, 45, 1; Epicteto 3, 1, 1; Josefo, Ant. 3, 228; em obra apologética [Taciano 15, 2, <span class=\"greek\">Περὶ</span> <span class=\"greek\">ζώων</span>] como título), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:11</a>; 1Cl 20:4, 10; 33:3; B 10:7s.; Ox 840, 4 (ver J. Jeremias, ConNeot 11, 1948, 98); Hm 12, 4, 1, variante de leitura; GJs 3:2 (animais domesticados; ver de Strycker, ad loc., em contraste com <span class=\"greek\">τὸ</span> … <span class=\"greek\">λογικὸν</span> <span class=\"greek\">ζῶον</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span>, Justino, D. 93, 3). <span class=\"greek\">ἄλογα</span> <span class=\"greek\">ζῷα</span>, «animais irracionais» (ver <span class=\"greek\">ἄλογος</span> 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:12</a>; Jd 10.</p><p class=\"entry-text\">② <strong>Criatura que transcende as categorias descritivas comuns e frequentemente combina formas diferentes; ser vivente</strong> (cf. Diodoro Sículo 4, 47, 3, de dragão; OGI 90, 31, <span class=\"greek\">τῷ</span> <span class=\"greek\">τε</span> <span class=\"greek\">Ἄπει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Μνεύει</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">ἱεροῖς</span> <span class=\"greek\">ζῴοις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Αἰγύπτῳ</span>; PTebt 5, 78 [118 a.C.]; 57, 12; POxy 1188, 4; Herm. Wr. 11, 7; Atanásio 18, 3; Deus não é <span class=\"greek\">σύνθετον</span> <span class=\"greek\">ζῶον</span>, «animal composto», Justino, D. 114, 3; Atanásio 6, 3; de embrião, Atanásio 35, 2). Referindo-se à ave fabulosa fênix, 1Cl 25:3. Sobre os quatro seres singulares diante do trono de Deus, cuja descrição em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:6</a>–9 lembra os <span class=\"greek\">ζῷα</span> de Ez 1:5ss., isto é, os querubins; ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5:6</a>, 8, 11, 14; 6:1, 3, 5–7; 7:11; 14:3; 15:7; 19:4.</p><p class=\"entry-text\">③ Uma passagem isolada de nossa literatura apresenta <span class=\"greek\">ζῶα</span> no sentido de <strong>criaturas vivas, incluindo pessoas e animais</strong> (Cornuto 16, p. 20, 20; Élio Aristides 45, 32 K.; Josefo, Ant. 1, 41; Justino, D. 4, 2; 107, 2), 1Cl 9:4. — S. Lonsdale, «Attitudes towards Animals in Ancient Greece», <em>Greece and Rome</em>, 2.ª série, 26, 1979, 146–59 (bibliografia); B. 137; DELG, s.v. <span class=\"greek\">ζώω</span>; M-M; TW.</p></section></article>\n<article id=\"entry-zoopoieo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ζωοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">ζωός</span> + <span class=\"greek\">ποιέω</span>; Nestle registra grafia com iota subscrito, mas <span class=\"greek\">ζωοπ</span>- é correto; ver B-D-F §26 e início de <span class=\"greek\">ζῷον</span>). Futuro <span class=\"greek\">ζωοποιήσω</span>; primeiro aoristo <span class=\"greek\">ἐζωοποίησα</span> (LXX; Melitão, P. 101, 776); infinitivo <span class=\"greek\">ζωοποιῆσαι</span>; passiva <span class=\"greek\">ἐζωοποιήθην</span>, Hm 4, 3, 7; particípio <span class=\"greek\">ζωοποιηθείς</span> (AcPlCor 2:8). Aristóteles, Teofrasto e outros; Herm. Wr.; LXX; TestGad 4:6; JosAs 8:2, 10; EpArist 16; Melitão; Atanásio, R. 51, 22; <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">ζ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">κινεῖ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>, Orígenes, C. Cels. 6, 48, 17. Em outras literaturas (por exemplo, Aristóteles e Teofrasto), <span class=\"greek\">ζ</span>. equivale a <span class=\"greek\">ζωογονέω</span>, «propagar seres vivos». Na LXX e no NT:</p><p class=\"entry-text\">① <strong>Fazer viver, dar vida, vivificar</strong>, especialmente em sentido transcendente.</p><p class=\"entry-text\">ⓐ Com Deus, Cristo ou o Espírito como sujeito. De Deus (<span class=\"greek\">ὁ</span> <span class=\"greek\">θεραπεύων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζ</span>., Teófilo de Antioquia 1, 7 [p. 72, 17]), que <span class=\"greek\">ζ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, «dá vida a todas as coisas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 6:13</a>, variante de leitura (por <span class=\"greek\">ζῳογονοῦντος</span>; cf. 2Esd 19:6). Especialmente dos mortos chamados de volta à vida: <span class=\"greek\">τοὺς</span> <span class=\"greek\">νεκρούς</span>, «vivificar os mortos» (TestGad 4:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:21a</a> (cf. inscrição em M. Schwabe, Israel Exploration Journal 4, 1954, 249–61); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:17</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">θνητὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">ὑμῶν</span>, «vossos corpos mortais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:11</a>; <span class=\"greek\">θανατοῦνται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζωοποιοῦνται</span>, «são mortos e vivificados», Dg 5:12 (sobre o contraste, cf. 4Km 5:7). Cristo <span class=\"greek\">θανατωθεὶς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">ζῳοποιηθεὶς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πνεύματι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 3:18</a>. Mediante seu sofrimento (= «morte»; ver <span class=\"greek\">πάσχω</span> 3a<span class=\"greek\">α</span>), Cristo vivifica os crentes, B 12:5 (para 7:2, ver b adiante). <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ζῳοποιηθήσονται</span>, «em Cristo todos serão vivificados», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:22</a>. O Espírito é chamado vivificante, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.63\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:63</a>; em contraste com a letra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:6</a>. Também Cristo, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔσχατος</span> <span class=\"greek\">Ἀδάμ</span>, <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ζῳοποιοῦν</span>, «o último Adão tornou-se espírito vivificante», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.45\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:45</a>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> … <span class=\"greek\">ἐζητήθη</span> <span class=\"greek\">ἵνα</span> <span class=\"greek\">ζωοποιηθῇ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆ</span> <span class=\"greek\">υἱοθεσίας</span>, «[a humanidade] foi procurada [por seu Pai] a fim de ser restituída à vida pela adoção», AcPlCor 2:7s.</p><p class=\"entry-text\">ⓑ Sobre coisas, circunstâncias e palavras: a lei não pode vivificar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:21</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">ζωοποιούμενοι</span> <span class=\"greek\">ζήσομεν</span>, «pela palavra seremos conservados vivos e [verdadeiramente] viveremos», B 6:17b; pela palavra do Pastor, <span class=\"greek\">ἐζωοποιήθην</span>, «sinto uma vida nova», Hm 4, 3, 7. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πληγὴ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ζωοποιήσῃ</span> <span class=\"greek\">ἡμᾶς</span>, «para que sua ferida nos dê vida», B 7:2. <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">νεκρὸς</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">ζωοποιῆσαι</span>, «embora ela [a serpente de Nm 21:8s.] esteja morta, pode dar vida», como figura de Cristo, B 12:7. O batismo vivifica, Hs 9, 16, 2; cf. 9, 16, 7. <span class=\"greek\">κολαζόμενοι</span> <span class=\"greek\">χαίρουσιν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ζωοποιούμενοι</span>, «quando são punidos, alegram-se por terem consciência de que estão sendo despertados para a vida», Dg 5:16 (ver <span class=\"greek\">ὡς</span> 3a<span class=\"greek\">β</span>). Cf. a imagem paulina da semente que brota, <span class=\"greek\">ὸ</span>̔ <span class=\"greek\">σπείρεις</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">ζῳοποιεῖται</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀποθάνῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:36</a> (Geopon. 9, 11, 7; Herm. Wr. 9, 6).</p><p class=\"entry-text\">② <strong>Manter vivo, sustentar a vida</strong>, do leite que alimenta uma criança: <span class=\"greek\">γάλακτι</span> <span class=\"greek\">ζωοποιεῖται</span>, «é mantida viva pelo leite», B 6:17a (ilustração da palavra divina; ver 1b). — DELG, s.v. <span class=\"greek\">ζώω</span>; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-zosimos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζώσιμος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Inscrições, papiros [Preisigke, <em>Namenbuch</em>]). <strong>Zósimo</strong>, mártir, Pol 9:1 (em companhia de Rufo, como também em CIG 192; 244; 1969; 3664).</p></section></article>\n<article id=\"entry-zotion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ζωτίων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Em geral, escrito <span class=\"greek\">Σωτίων</span> em outras fontes, inscrições e papiros.) <strong>Zótion</strong>, auxiliar eclesiástico em Magnésia, IMgMai 2.</p></section></article>\n<article id=\"entry-eta-numeral-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">η´</h1><div class=\"entry-meta\"><span>sinal numérico grego</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Sinal numérico correspondente a <strong>8</strong> (<span class=\"greek\">ὀκτώ</span>; Josefo, C. Ap. 1, 126), B 9:8; ou «oitavo» (<span class=\"greek\">ὀγδόη</span> [<span class=\"greek\">ἐπιστολή</span>]), Hm 8; [Hs 8] em sobrescritos (Apolônio Paradoxógrafo 41, <span class=\"greek\">Θεόφραστος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">η</span>´ <span class=\"greek\">περὶ</span> <span class=\"greek\">φυτῶν</span>).</p></section></article>\n<article id=\"entry-e-disjunctive-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤ</h1><div class=\"entry-meta\"><span>partícula disjuntiva e comparativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong><span class=\"greek\">ἤ</span></strong>, partícula (Homero e autores posteriores).</p><p class=\"entry-text\"><strong>① Marcador de alternativa, «ou»; partícula disjuntiva</strong> (B-D-F §446; Rob. 1188s.).</p><p class=\"entry-text\">ⓐ Separando:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Opostos mutuamente excludentes: <span class=\"greek\">λευκὴν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μέλαιναν</span>, «branca ou preta», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:36</a>; <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ἐκεῖ</span> [<span class=\"greek\">ἢ</span>] <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ὧδε</span>, «eis ali [ou] eis aqui», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:23</a>; <span class=\"greek\">ψυχρὸς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζεστός</span>, «frio ou quente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:15</a>; <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀνθρώπων</span>, «de Deus ou dos homens», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:25</a>; <span class=\"greek\">δοῦναι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οὔ</span>, «dar ou não [dar]», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:17</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:14</a>; <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κακοποιῆσαι</span>, «fazer o bem ou fazer o mal», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:11</a> (cf. Atanásio 2:4, <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πονηρός</span>).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Termos relacionados ou semelhantes, dos quais um pode substituir ou completar o outro: <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">προφήτας</span>, «a lei ou os profetas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a> (JosAs 2:11, <span class=\"greek\">ἀνὴρ</span> … <span class=\"greek\">ἢ</span> <span class=\"greek\">παιδίον</span> <span class=\"greek\">ἄρρεν</span>; Justino, D. 93, 4, <span class=\"greek\">φιλίαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀγάπην</span>; escólio a Sófocles, Oed. Col. 380 Papag., <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐστί</span>); <span class=\"greek\">πόλιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κώμην</span>, «cidade ou aldeia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:11</a>; <span class=\"greek\">ἔξω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκίας</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span> <span class=\"greek\">ἐκείνης</span>, «fora daquela casa ou daquela cidade», versículo 14; <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μητέρα</span>, «pai ou mãe», versículo 37; <span class=\"greek\">τέλη</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">κῆνσον</span>, «tributos ou imposto», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:25</a>; <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀποκριθῆτέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀπολύσητε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:68</a>, variante de leitura; <span class=\"greek\">πρόσκομμα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">σκάνδαλον</span>, «obstáculo ou escândalo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:13</a>; cf. versículo 21, variante; <span class=\"greek\">εἰς</span> <span class=\"greek\">τίνα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ποῖον</span> <span class=\"greek\">καιρόν</span>, «para que tempo ou que espécie de tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:11</a>; <span class=\"greek\">νοῆσαι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">συνιέναι</span>, «perceber ou compreender», B 10:12. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:17</a>; 10:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 2:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 13:1</a>; AcPlCor 2:26. Em enumerações, ocorrem até seis instâncias de <span class=\"greek\">ἤ</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:35</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4:15</a> (Justino, A II, 1, 2). <span class=\"greek\">ἤτε</span> … <span class=\"greek\">ἤτε</span> (Homero e outros; PRossGeorg III, 2, 4 [século III d.C.]), <span class=\"greek\">ἤτε</span> <span class=\"greek\">ἄρσενα</span> <span class=\"greek\">ἤτε</span> <span class=\"greek\">θήλειαν</span>, «quer menino, quer menina», GJs 4:1, papiro (<span class=\"greek\">εἴτε</span> … <span class=\"greek\">εἴτε</span> nos códices). <span class=\"greek\">ἢ</span> <span class=\"greek\">καὶ</span>, «ou [até, também]» (PLond III, 962, 5, p. 210 [254/261 d.C.]; EpJer 58), <span class=\"greek\">ἢ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τελώνης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:11</a>; cf. 11:12; 12:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:15</a>; 4:9; 14:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 16:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:13b</a>. <span class=\"greek\">ἤ</span> em lugar de <span class=\"greek\">καί</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:33</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:16</a>, variante.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span>, «ou … ou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; 12:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16:13</a>; AcPlCor 1:7s. <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span>, «ou … ou … ou» (Filodemo, <span class=\"greek\">οἰκ</span>. coluna 22, 41 Jensen; Justino, A I, 28, 4 e outros; Melitão, P. 36, 246s.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:6</a> (<span class=\"greek\">ἤ</span> quatro vezes, como em Libânio, Or. 28, p. 48, 15 F, e Or. 31, p. 130, 7; Justino, D. 85, 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:4</a>, variante de leitura. <span class=\"greek\">ἤτοι</span> … <span class=\"greek\">ἤ</span> (Heródoto, Tucídides e outros [ver Kühner-G. II 298]; PTebt 5, 59; PRyl 154, 25; Sb 11:18; TestSol 10:28 C [sem <span class=\"greek\">ἤ</span>]; Fílon, Op. M. 37; Josefo, Ant. 18, 115; Justino, D. 6, 1; 100, 3; Atanásio 8, 1; R. 52, 26), «ou … ou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:16</a>.</p><p class=\"entry-text\">ⓒ Em enunciados negativos, <span class=\"greek\">ἤ</span> assume o valor de «nem» ou «ou» quando introduz o segundo, terceiro etc. elemento: <span class=\"greek\">ἰῶτα</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μία</span> <span class=\"greek\">κεραία</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παρέλθῃ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:18</a>; <span class=\"greek\">πῶς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τί</span>, «como ou o que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:19</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:7</a>; <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐδόξασαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ηὐχαρίστησαν</span>, «não glorificaram nem deram graças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:21</a>; <span class=\"greek\">διαθήκην</span> <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">ἀθετεῖ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐπιδιατάσσεται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:15</a>; <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">δύνηται</span> <span class=\"greek\">ἀγοράσαι</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πωλῆσαι</span>, «para que ninguém possa comprar nem vender», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:12</a>. O mesmo ocorre em perguntas retóricas negativas; o inglês contemporâneo, por tornar negativa a frase toda, requer a tradução por «or», correspondente a «ou»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:12</a>.</p><p class=\"entry-text\">ⓓ Em geral, <span class=\"greek\">ἤ</span> aparece frequentemente em frases interrogativas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Introduzindo e acrescentando perguntas retóricas (Justino, D. 2, 4 e outros; Atanásio 8:3 e outros): <span class=\"greek\">ἢ</span> <span class=\"greek\">δοκεῖς</span> <span class=\"greek\">ὅτι</span>;, «ou pensas que?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a>; <span class=\"greek\">ἢ</span> <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μόνον</span>;, «ou Deus é somente dos judeus?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:29</a>; <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀγνοεῖτε</span>;, «ou ignorais?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:3</a>; 7:1; também <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἴδατε</span>;, «ou não sabeis?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:9</a>, 16, 19; cf. 10:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:7</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Introduzindo pergunta paralela à anterior ou que a complementa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:10</a>; <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνέγνωτε</span> … ; <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνέγνωτε</span> … ;, «não lestes …? Ou não lestes …?», Mt 12:(3), 5; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:6</a> (cf. Justino, D. 27, 5 e outros; Melitão, P. 74, 541, <span class=\"greek\">ἢ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γέγραπταί</span> <span class=\"greek\">σοι</span> …); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:1</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. No segundo membro de perguntas duplas diretas ou indiretas: <span class=\"greek\">πότερον</span> … <span class=\"greek\">ἤ</span> (Ésquilo, Heródoto e outros), «se … ou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7:17</a>; B 19:5; D 4:4; Hs 9, 28, 4. <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span> … <span class=\"greek\">ἤ</span>, «se … ou … ou … ou» (Homero; Teógnis 913s.; oráculo em Heródoto 1, 65, 3; Teócrito 25, 170s. e outros; Kühner-G. II 530, 12), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:35</a>. Normalmente o primeiro membro não contém a partícula: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:10</a>; 3:2, 5.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Com palavra interrogativa, normalmente após outra pergunta: <span class=\"greek\">ἢ</span> <span class=\"greek\">τίς</span>;, «ou quem?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:31</a>; 20:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:1</a>; 2Cl 1:3; 6:9; <span class=\"greek\">τίς</span> … ; <span class=\"greek\">τίς</span> … ; <span class=\"greek\">ἢ</span> <span class=\"greek\">τίς</span> … ;, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:7</a>; <span class=\"greek\">τί</span> … ; <span class=\"greek\">ἢ</span> <span class=\"greek\">τί</span> … ;, «o quê …? Ou o quê?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7:16</a>; <span class=\"greek\">ἢ</span> <span class=\"greek\">πῶς</span>, <span class=\"greek\">ἢ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐρεῖς</span>;, «ou como podes dizer?», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:4</a>; cf. 12:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:42</a>, variante de leitura (cf. JosAs 6:2; Taciano 17, 3 e outros).</p><p class=\"entry-text\"><strong>② Partícula de comparação: «do que», «antes do que», «em vez de».</strong></p><p class=\"entry-text\">ⓐ Após comparativo, antes do outro membro comparado: <span class=\"greek\">ἀνεκτότερον</span> … <span class=\"greek\">ἤ</span>, «mais tolerável … do que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:15</a>; cf. 11:22, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:12</a>; <span class=\"greek\">εὐκοπώτερον</span> … <span class=\"greek\">ἤ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:25</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:1</a>; <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἤ</span>, «mais … do que», «antes … do que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:19</a>; 5:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:15</a>; 1Cl 2:1a; 14:1; 21:5. Sobre numerais sem <span class=\"greek\">ἤ</span> depois de <span class=\"greek\">πλείων</span> e <span class=\"greek\">ἐλάσσων</span>, como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:53</a> (<span class=\"greek\">πλείους</span> <span class=\"greek\">ἤ</span> como variante e em edições diversas), ver B-D-F §185, 4 (cf. comparação em Atanásio 16, 8, <span class=\"greek\">μηδὲν</span> <span class=\"greek\">πλέον</span> [<span class=\"greek\">ἢ</span> corr.] <span class=\"greek\">ὅσον</span> <span class=\"greek\">ἐκελεύσθησαν</span>).</p><p class=\"entry-text\">ⓑ Também sem comparativo precedente (Kühner-G. II 303; B-D-F §245, 3).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com verbos sem <span class=\"greek\">μᾶλλον</span> (Jó 42:12): <span class=\"greek\">χαρὰ</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἐνενήκοντα</span> <span class=\"greek\">ἐννέα</span>, «haverá mais alegria por um do que por noventa e nove», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15:7</a>; <span class=\"greek\">λυσιτελεῖ</span> … <span class=\"greek\">ἤ</span>, «seria melhor … do que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:2</a> (cf. Andócides 1, 125, <span class=\"greek\">τεθνάναι</span> <span class=\"greek\">νομίσασα</span> <span class=\"greek\">λυσιτελεῖν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζῆν</span>; Tb 3:6 BA); <span class=\"greek\">θέλω</span> … <span class=\"greek\">ἤ</span>, «prefiro … a», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:19</a> (cf. Epicteto 3, 1, 41; BGU 846, 16 [século II d.C.], <span class=\"greek\">θέλω</span> <span class=\"greek\">πηρὸς</span> <span class=\"greek\">γενέσται</span> [= <span class=\"greek\">γενέσθαι</span>], <span class=\"greek\">εἲ</span> [= <span class=\"greek\">ἢ</span>] <span class=\"greek\">γνοῦναι</span>, <span class=\"greek\">ὅπως</span> <span class=\"greek\">ἀνθρόπῳ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὀφείλω</span> <span class=\"greek\">ὀβολόν</span>, «preferiria ficar mutilado a saber que ainda devo um óbolo a alguém» [1/6 de uma dracma]; Os 6:6; 2Mc 14:42; Josefo, Ant. 18, 59; Justino, A I, 15, 8). <span class=\"greek\">βούλομαι</span> … <span class=\"greek\">ἤ</span>, «preferiria … a», já em Homero, por exemplo, Ilíada 1, 117.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Depois do grau positivo (já em Heródoto 9, 26): <span class=\"greek\">καλόν</span> <span class=\"greek\">ἐστιν</span> … <span class=\"greek\">ἤ</span>, «é melhor … do que», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:8</a>, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9:43</a>, 45, 47; 1Cl 51:3 (Gn 49:12; Sl 117:8s.; Eclo 20:25; 22:15; Jn 4:3, 8; 4Mc 9:1; cf. Polieno 8, 49, <span class=\"greek\">καλὸν</span> <span class=\"greek\">ἀποθανεῖν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζῆν</span>; Filemom, <em>Com.</em> n.º 203, <span class=\"greek\">θανεῖν</span> <span class=\"greek\">κράτιστόν</span> [= «muito melhor»] <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζῆν</span> <span class=\"greek\">ἀθλίως</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">ἤ</span> empregado na comparação com ideia de exclusão (Pseudo-Calístenes 1, 37, 4, <span class=\"greek\">μέμφεσθε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐμέ</span>, «censurai vosso rei, não a mim»; Gn 38:26, <span class=\"greek\">δεδικαίωται</span> <span class=\"greek\">Θαμαρ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐγώ</span>; 2Km 19:44; Justino, A I, 15, 8, a respeito de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:32</a>, <span class=\"greek\">θέλει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κόλασιν</span>): <span class=\"greek\">δεδικαιωμένος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐκεῖνος</span>, «justificado antes que [e não] aquele outro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:14</a>, variante de leitura.</p><p class=\"entry-text\">ⓒ <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">ἤ</span>, «nada diferente de», «nada senão» (cf. Xenofonte, Cyr. 2, 3, 10; 7, 5, 41; Josefo, Ant. 8, 104; Taciano 15, 2; também <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἄλλο</span> … <span class=\"greek\">ἤ</span>, Justino, A I, 33, 6 e outros; Atanásio 18, 1, <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> … <span class=\"greek\">ἕτερον</span> <span class=\"greek\">τρόπον</span> … <span class=\"greek\">ἢ</span> <span class=\"greek\">τοῦτον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:21</a>. <span class=\"greek\">τί</span> … <span class=\"greek\">ἤ</span>, «que outra coisa … senão» (Xenofonte, Oec. 3, 3; TestJob 42:5; Kühner-G. II 304, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:21</a>.</p><p class=\"entry-text\">ⓓ <span class=\"greek\">πρὶν</span> <span class=\"greek\">ἤ</span>, «antes que» (jonismo muito raro nos escritores áticos, mas comum na coiné; por exemplo, Nicolau de Damasco: 90 Fgm. 130, 14, p. 397, 9 Jac.; Diodoro Sículo 1, 64, 7; 1, 92, 4; Josefo, Ant. 8, 345; Justino, A I, 12, 10 e outros; Taciano 6:1 e outros; A. Tschuschke, <em>De <span class=\"greek\">πρίν</span> particulae apud scriptores aetatis Augusteae prosaicos usu</em>, dissertação, Breslávia, 1913, 31, 33; ver também <span class=\"greek\">πρίν</span> a).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Seguido de infinitivo aoristo (Eliano, VH 1, 5; Herodiano 2, 3, 2; Sb 2:8; Eclo 11:8 e outros) e acusativo associado (Nicolau de Damasco: 90 Fgm. 128, 14 [<span class=\"greek\">Βίος</span>], p. 397, 9 Jac.; Eliano, VH 1, 21; PSI 171, 25 [século II a.C.]; Eclo 48:25; Tb 2:4; 3:8; 8:20; TestReub 1:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:2</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Seguido de subjuntivo aoristo e <span class=\"greek\">ἄν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:26</a> (sem <span class=\"greek\">ἄν</span>, Josefo, Ant. 4, 10).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Seguido de optativo presente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:16</a>.</p><p class=\"entry-text\">ⓔ Em combinação com outras partículas.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἤ</span>, ver <span class=\"greek\">ἀλλά</span> 1a.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">ἤπερ</span>, «do que» (Homero, Ilíada 1, 260; 9, 26, 7; Heródoto; Políbio 2, 51; 61; 2Mc 14:42; 4Mc 15:16; Josefo, Bell. 5, 10; Ant. 18, 62; Justino, A I, 29, 1), depois de <span class=\"greek\">μᾶλλον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:43</a> (cf. Tb 14:4 S, <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Μηδίᾳ</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">σωτηρία</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἤπερ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ἀσσυρίοις</span>; Taciano 13, 3; 14, 1; sem <span class=\"greek\">μᾶλλον</span>, Taciano 40, 1; Diodoro Sículo 13, 60, 3, <span class=\"greek\">πλείονα</span> <span class=\"greek\">ἤπερ</span>); depois de <span class=\"greek\">πλέον</span>, IEph 6:2 (latim). <span class=\"greek\">ἢ</span> <span class=\"greek\">γάρ</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:14</a>, variante de leitura, pode derivar de <span class=\"greek\">ἤ</span> + <span class=\"greek\">παρ</span>’. — DELG; M-M; EDNT.</p></section></article>\n<article id=\"entry-e-affirmative-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἦ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><strong>Verdadeiramente, de fato.</strong> Talvez se deva acentuar assim a palavra em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:10</a>, 15 (Justino; também Atanásio, R. 53, 7 e outros). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:14</a>, variante de leitura; <span class=\"greek\">ἦ</span> <span class=\"greek\">μήν</span> (Homero e outros; Josefo, Ant. 15, 368; 17, 72), «certamente, de fato», por <span class=\"greek\">εἰ</span> <span class=\"greek\">μήν</span>, de som semelhante. Em Hs 9, 17, 5, Funk escreve <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἦ</span> <span class=\"greek\">χείρονες</span>; a leitura correta provavelmente é <span class=\"greek\">μ</span>. <span class=\"greek\">δ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">χ</span>. Em GJs 19:3, papiro, <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πιστεύσω</span> <span class=\"greek\">η</span> [interrogativo <span class=\"greek\">ἦ</span>, B-D-F §440, 3] <span class=\"greek\">παρθένος</span> <span class=\"greek\">ἐγέννησεν</span>, em oposição aos códices, … <span class=\"greek\">πιστεύσω</span> ‹<span class=\"greek\">ὅτι</span>› <span class=\"greek\">ἡ</span> <span class=\"greek\">παρθένος</span> <span class=\"greek\">ἐγ</span>. (sobre a passagem, ver de Strycker). — Denniston 279–88; DELG; M-M.</p></section></article>\n<article id=\"entry-egagon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤγαγον</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἄγω</span>.</p></section></article>\n<article id=\"entry-hegemoneuo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡγεμονεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">ἡγεμών</span>; Homero e autores posteriores; SIG 877, 5; OGI 493, 24; PTebt 302, 7; PRyl 113, 20; PStras 41, 17; Fílon, Josefo, Justino; SibOr 5, 348.) <strong>Exercer função administrativa, ser dirigente, comandar, governar, dar ordens</strong>, da administração de legados imperiais (governadores; ver <span class=\"greek\">ἡγεμών</span> 2; com esse sentido, o verbo ocorre em POslo 99, 3 [160/161 d.C.]; Josefo, Ant. 15, 345; Justino, A I, 29, 2). <span class=\"greek\">ἡγεμονεύοντος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Συρίας</span> <span class=\"greek\">Κυρηνίου</span>, «quando Quirino governava a Síria», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:2</a>. Sobre o governo de Quirino, ver F. Bleckmann, Klio 17, 1920, 104–12; H. Dessau, ibid. 252–58; R. Brown, <em>The Birth of the Messiah</em>, 1977, 547–56. Ver também <span class=\"greek\">ἀπογραφή</span> e <span class=\"greek\">Κυρήνιος</span>. Sobre Pôncio Pilatos, <span class=\"greek\">ἡγεμονεύοντος</span> <span class=\"greek\">Π</span>. <span class=\"greek\">Π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰουδαίας</span>, «quando Pôncio Pilatos era prefeito da Judeia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:1</a> (para isso, o códice D traz o menos preciso <span class=\"greek\">ἐπιτροπεύω</span>). — DELG, s.v. <span class=\"greek\">ἡγέομαι</span>; M-M.</p></section></article>\n<article id=\"entry-hegemonia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡγεμονία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">ἡγεμών</span>; Heródoto e autores posteriores; empréstimo ao vocabulário rabínico.) <strong>Condição de exercer controle oficial sobre outras pessoas; comando superior, direção, administração de um cargo elevado</strong>.</p><p class=\"entry-text\">ⓐ Do governo imperial (da dignidade régia, Heródoto 1, 7; 7, 2; EpArist 219; Josefo, Ant. 2, 348; inscrições desde a época de Augusto: ZNW 22, 1923, 16; sobre Nero, SIG 810, 16; Caio [Calígula], Fílon, Leg. ad Gai. 8, 168; Vespasiano, Josefo, Vi. 423), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:1</a>; 1Cl 61:1.</p><p class=\"entry-text\">ⓑ Do cargo de governador (Josefo, Ant. 18, 88, sobre legados da Síria; OGI 614, 4, sobre o propretor da Arábia; POxy 59, 10; 237 V, 6; PRyl 77, 36): <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡ</span>. <span class=\"greek\">Ποντίου</span> <span class=\"greek\">Πιλάτου</span>, «na época em que Pôncio Pilatos era prefeito», IMg 11. — DELG, s.v. <span class=\"greek\">ἡγέομαι</span>; M-M; TW.</p></section></article>\n<article id=\"entry-hegemonikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡγεμονικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver os dois verbetes anteriores e o seguinte; Xenofonte, Platão; UPZ 144, 28 [164 a.C.]; LXX; Fílon; Josefo, Bell. 2, 305; C. Ap. 2, 125.) <strong>Relativo à função de supervisão; que guia, dirigente, condutor.</strong> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἡγ</span>., «Espírito que guia», 1Cl 18:12 (Sl 50:14). Sobre <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">ἡγ</span>. e seus pressupostos filosóficos, ver Knopf, <em>Handbuch</em>, comentário à passagem; J. Schneider, ZNW 34, 1935, 62–69. — Sv.</p></section></article>\n<article id=\"entry-hegemon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡγεμών, όνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e autores posteriores; empréstimo ao vocabulário rabínico).</p><p class=\"entry-text\">① <strong>Aquele que governa, especialmente em posição eminente; governante, dirigente</strong> (Sófocles, Oed. R. 103; SIG 814, 25; Êx 15:15; Jó 42:17d; Josefo, Ant. 19, 217; talvez «chefe», Gn 36:15ss.; 1Cr 1:51ss.). <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἡγεμόσιν</span> <span class=\"greek\">Ἰούδα</span>, «entre os governantes de Judá», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a> (segundo Mq 5:1; a tradução <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡγεμόσιν</span> no lugar de <span class=\"greek\">ἐν</span> <span class=\"greek\">χιλιάσιν</span> da LXX, seguindo métodos interpretativos rabínicos, é sugerida por <span class=\"greek\">ἡγούμενον</span> em 2Km 5:2, citado na última parte de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a>; acerca da hipótese de que se encontre na base da passagem um equívoco sobre o texto original ou uma variante na tradição da LXX, ver os comentários).</p><p class=\"entry-text\">② <strong>Administrador imperial superior de uma província; governador</strong> (Díon Crisóstomo 31 [48], 1; Élio Aristides 50, 12 K. = 26, p. 505 D.; índice de OGI; papiros; Josefo, Ant. 15, 405), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:18</a>; 27:23, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 13:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2:14</a>. Especialmente procuradores ou prefeitos da Judeia: Pôncio Pilatos (Josefo, Ant. 18, 55, <span class=\"greek\">Πιλᾶτος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰουδαίας</span> <span class=\"greek\">ἡγεμών</span>; J. Vardaman, «A New Inscr. [Lat.] which Mentions Pilate as ‘Prefect’», JBL 81, 1962, 70s.; Boffo, <em>Iscrizione</em>, n.º 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:2</a>, 11, 14s., 21, 27; 28:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:20</a>; Félix, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:24</a>, 26, 33; 24:1, 10; Festo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:30</a>. — Jerônimo (em Epheus), AcPl Ha 1, 23. W. Liebenam, <em>Beiträge z. Verwaltungsgesch. d. röm. Reiches</em> I, 1886, 1ss.; Pauly-W. XXIII/1, 1240–79; G. Burton, «Provincial Procurators and the Public Provinces», Chiron 23, 1993, 13–28; L. Robert, AntCl 62, 1960, 329; DELG, s.v. <span class=\"greek\">ἡγέομαι</span>; EDNT; M-M.</p></section></article>\n<article id=\"entry-hegeomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡγέομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἡγήσομαι</span>, LXX; primeiro aoristo <span class=\"greek\">ἡγησάμην</span>; perfeito <span class=\"greek\">ἥγημαι</span> (ver os quatro verbetes precedentes; Homero e autores posteriores).</p><p class=\"entry-text\">① <strong>Exercer função de liderança, dirigir, guiar</strong>. Em nossa literatura, apenas particípio presente (<span class=\"greek\">ὁ</span>) <span class=\"greek\">ἡγούμενος</span>, de homens em posição dirigente (Sófocles, Phil. 386; frequente em Políbio; Diodoro Sículo 1, 4, 7; 1, 72, 1; Luciano, Alex. 44, 57; inscrições, papiros, LXX, EpArist; TestZeb 10:2; ViEzk 2 [p. 74, 7 Sch.]; Justino, A II, 1, 1; Taciano; Melitão, HE 4, 26, 10; Atanásio 1, 2): «governante, líder», em contraste com <span class=\"greek\">ὁ</span> <span class=\"greek\">διακονῶν</span>, «o servo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:26</a>. Da autoridade principesca (Ez 43:7; Eclo 17:17; 41:17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a>; 1Cl 32:2; 60:4. De altos funcionários, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:10</a>; MPol 9:3 (lido por Eusébio em lugar de <span class=\"greek\">ἀνθυπάτου</span>); 1Cl 5:7; 51:5; 55:1. De comandantes militares (Apiano, Iber. 78 §333; Bell. Civ. 3, 26 §97; 1Mc 9:30; 2Mc 14:16), 1Cl 37:2s. Também de líderes de corporações religiosas (PTebt 525, <span class=\"greek\">Παεῦς</span> <span class=\"greek\">ἡγούμενος</span> <span class=\"greek\">ἱερέων</span>; PLond II, 281, 2, p. 66 [66 d.C.]; PVindBosw 1, 31 [87 d.C.], <span class=\"greek\">τῶν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἱεροῦ</span> <span class=\"greek\">ἡγουμένων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πρεσβυτέρων</span>; cf. Eclo 33:19, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἡγούμενοι</span> <span class=\"greek\">ἐκκλησίας</span>; Sb 7835 [século I a.C.], 10, 14, o <span class=\"greek\">ἡγούμενος</span> [monárquico] da confraria cultual de Zeus Hipsisto), dos dirigentes de congregação cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:7</a>, 17, 24; 1Cl 1:3. <span class=\"greek\">ἄνδρας</span> <span class=\"greek\">ἡγουμένους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀδελφοῖς</span>, «homens de liderança entre os irmãos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:22</a>. F. Büchsel, TW II 909s. De Paulo, tomado por Hermes, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἡγούμενος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span>, «o principal orador», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:12</a> (Cyranides, p. 15, 30, Hermes como <span class=\"greek\">λόγων</span> <span class=\"greek\">ἡγούμενος</span>; Jâmblico, Myst. [Herm. Wr. IV, p. 28, 4 Sc.], Hermes <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λόγων</span> <span class=\"greek\">ἡγεμών</span>; ver também <span class=\"greek\">Ἑρμῆς</span> 1).</p><p class=\"entry-text\">② <strong>Envolver-se num processo intelectual; pensar, considerar, julgar, reputar</strong> (poetas trágicos, Heródoto e outros). <span class=\"greek\">ἀναγκαῖον</span>, «necessário», seguido de infinitivo (ver <span class=\"greek\">ἀναγκαῖος</span> 1; cf. BGU 824, 4; PRyl 235, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:25</a>. <span class=\"greek\">δίκαιον</span>, «justo», seguido de infinitivo, «considero meu dever», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:13</a> (Justino, A I, 4, 2; D. 125, 1). <span class=\"greek\">περισσὸν</span> <span class=\"greek\">ἡγεῖσθαι</span>, com infinitivo articular, «considerar supérfluo» (POxy 1070, 17, <span class=\"greek\">τὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">γράφειν</span> … <span class=\"greek\">περιττὸν</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἡγησάμην</span>), Dg 2:10. Seguido de acusativo com infinitivo (Heródoto 3, 8, 3; SIG 831, 13; Fílon, Agr. 67; Josefo, Ant. 19, 107; Justino, A I, 9, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:8a</a> (ver também <span class=\"greek\">ζημία</span>); <span class=\"greek\">ἀποστόλους</span> <span class=\"greek\">πιστοὺς</span> <span class=\"greek\">ἡγησάμενος</span> <span class=\"greek\">εἶναι</span>, PtK 3, p. 15, 18. Com duplo acusativo: «considerar alguém ou algo [como] alguém ou algo» (Ésquilo, Heródoto e outros; Sb 1:16; 7:8; Fílon, Cher. 70; Josefo, Ant. 7, 51; Justino, A I, 9, 3; D. 12, 1 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.2\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:2</a> (perfeito <span class=\"greek\">ἥγημαι</span> com sentido presente, como Heródoto 1, 126; Platão, Tim. 19e; POslo 49, 3 [cerca de 100 d.C.]; Jó 42:6); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:3</a>, 6; 3:7, 8b (= AcPl Ha 2, 23); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:12</a>; 6:1 (Jó 30:1; JosAs 3:4, códice A [p. 42, 20 Bat.]); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:29</a>; 11:11, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:13</a>; 3:15; em 3:9, um acusativo é fornecido pelo contexto; Hv 2, 1, 2; Dg 2:6; 9:6. Também <span class=\"greek\">τινὰ</span> <span class=\"greek\">ὥς</span> <span class=\"greek\">τινα</span>, «alguém como alguém», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 3:15</a>; cf. 2Cl 5:6; Hv 1, 1, 7 (<span class=\"greek\">ὡς</span> como em Fílon, Agr. 62; cf. Jó 19:11; 33:10; Taciano 34, 1). <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">χαρὰν</span> <span class=\"greek\">ἡγήσασθε</span>, <span class=\"greek\">ὅταν</span> …, «considerai motivo de inteira alegria quando …», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:2</a> (cf. POxy 528, 8, <span class=\"greek\">πένθος</span> <span class=\"greek\">ἡγούμην</span>; Justino, D. 14, 2, <span class=\"greek\">ἡγεῖσθε</span> <span class=\"greek\">εὐσέβειαν</span>, <span class=\"greek\">ἐάν</span> …). <span class=\"greek\">μωρίαν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">εἰκὸς</span> <span class=\"greek\">ἡγοῖντ</span>’ <span class=\"greek\">ἄν</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">θεοσέβειαν</span>, «deveriam considerá-lo antes loucura do que reverência a Deus», Dg 3:3; cf. 4:5. Também na passiva: <span class=\"greek\">ἐκείνη</span> <span class=\"greek\">βεβαία</span> <span class=\"greek\">εὐχαριστία</span> <span class=\"greek\">ἡγείσθω</span>, «seja considerada válida [somente] aquela celebração da Eucaristia», ISm 8:1. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:13</a>, emerge para <span class=\"greek\">ἡ</span>. o sentido «estimar, respeitar» (ver Mitt-Wilck. I/2, 116, 4s. [séculos II/III d.C.], <span class=\"greek\">ἡγοῦ</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πατρῴους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σέβου</span> <span class=\"greek\">῏Ισιν</span>). — B. 711; 1204; DELG; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-edein-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ᾔδειν</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">οἶδα</span>.</p></section></article>\n<article id=\"entry-hedeos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡδέως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Advérbio de <span class=\"greek\">ἡδύς</span> (Sófocles, Hipócrates e outros). Indica satisfação ligada a alguma coisa: <strong>com prazer, de bom grado</strong> (Aristófanes, Tucídides e outros). Com <span class=\"greek\">λαμβάνειν</span>, «receber com prazer» (Aristófanes, Equ. 440), ITr 6:2. <span class=\"greek\">ἡδ</span>. <span class=\"greek\">ἀκούειν</span>, «gostar de ouvir» (Josefo, Ant. 3, 191; Justino, D. 10, 4; 59, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:20</a>; 12:37; Hm 2:2. <span class=\"greek\">ἀνέχεσθαι</span>, «suportar com prazer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.19\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11:19</a>. <span class=\"greek\">ἡδ</span>. <span class=\"greek\">ποιεῖν</span>, «fazer de bom grado» (Pseudo-Menandro, Dist. Fgm. 704 Kock; POxy 113, 30; PGrenf II, 73, 20), Hs 6, 5, 5. Com <span class=\"greek\">βαστάζειν</span>, «carregar de bom grado», Hs 8, 10, 3; 9, 14, 6; com <span class=\"greek\">ὑποδέχεσθαι</span>, «receber de bom grado», Hs 8, 10, 3; 9, 27, 2. <span class=\"greek\">Ἰσαὰκ</span> <span class=\"greek\">ἡδ</span>. <span class=\"greek\">προσήγετο</span> <span class=\"greek\">θυσία</span>, «Isaque deixou-se conduzir de bom grado como sacrifício», 1Cl 31:3. <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">ἡδέως</span> <span class=\"greek\">ἔχει</span>, «[a criança] de quem até César gosta», Ox 849, 16s. Texto restaurado: [<span class=\"greek\">ἡδέως</span> <span class=\"greek\">θλείβον</span>]<span class=\"greek\">ται</span>, Hs 8, 10, 4s. (ver Bonner 113, 18s., baseado no latim libenter patiuntur). Comparativo <span class=\"greek\">ἥδιον</span> (Lísias 7, 40; IPriene 105, 19 [cerca de 9 a.C.]; BGU 372 I, 15; Eclo 22:11; Justino, D. 29, 1), «mais prazerosamente»: <span class=\"greek\">ἥδ</span>. <span class=\"greek\">διδόναι</span>, 1Cl 2:1 (cf. <span class=\"greek\">μακάριος</span> 2b<span class=\"greek\">γ</span>); <span class=\"greek\">ὑπομιμνῄσκειν</span>, 1Cl 62:3. Superlativo com força elativa (B-D-F §60, 2; Rob. 278s.; 670; M-M, s.v.), <span class=\"greek\">ἥδιστα</span>, «com grande prazer» (Platão, Theaet. 183d; Luciano, Scyth. 8; POxy 1061, 21 [22 a.C.]; 933, 5; PLond III, 897, 8, p. 207 [84 d.C.]; Josefo, Vi. 365), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:8</a>, códice D. <span class=\"greek\">ἥδιστα</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">καυχήσομαι</span>, «gloriar-me-ei ainda mais prazerosamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:9</a> (ver B-D-F §246). — B. 1032; DELG, s.v. <span class=\"greek\">ἥδομαι</span> B (<span class=\"greek\">ἡδύ</span>); M-M; Spicq.</p></section></article>\n<article id=\"entry-ede-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἤδη</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Homero e autores posteriores; contraste entre <span class=\"greek\">ἤδη</span>, «já», e <span class=\"greek\">ἔτι</span>, «ainda», Cáriton 49).</p><p class=\"entry-text\">① <strong>Ponto temporal anterior a outro, com implicação de conclusão: agora, já, a esta altura</strong>.</p><p class=\"entry-text\">ⓐ Com tempo presente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; 15:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:37</a>; 8:2; 11:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:6</a>; 21:30 (com <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">εἶναι</span>, como em Josefo, Ant. 6, 223); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:36</a> (se <span class=\"greek\">ἤδη</span> pertence à frase precedente, versículo 35, comparar sua posição em Tb 3:6 BA; Josefo, Ant. 3, 48); 11:39 e outros: «agora» (Apiano, Bell. Civ. 5, 21 §82, <span class=\"greek\">ἤδη</span> <span class=\"greek\">λέγουσα</span>; Justino, D. 43, 3). <span class=\"greek\">ἤδη</span> <span class=\"greek\">καί</span>, «até agora, mesmo já» (3Mc 3:10; 6:24; Josefo, Ant. 16, 100), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 3:9</a>. De modo semelhante, <span class=\"greek\">νῦν</span> <span class=\"greek\">ἤδη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:3</a> (Justino, D. 137, 4, <span class=\"greek\">καὶ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">ἤδη</span>; cf. 55, 1, <span class=\"greek\">τὰ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἤδη</span>). Também «imediatamente» (Polieno 6, 8): <span class=\"greek\">γινώσκεται</span> <span class=\"greek\">ἤδη</span>, «sabemos imediatamente», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 21:30</a>, códice D.</p><p class=\"entry-text\">ⓑ Com tempo passado (Justino, A I, 42, 1, <span class=\"greek\">ὡς</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">γενόμενα</span> e outros): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:15</a>, 24; 17:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:35</a>; 13:28; 15:42, 44, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:49</a> e outros. <span class=\"greek\">σῶμα</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">νενεκρωμένον</span>, «corpo já amortecido», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:19</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">πεφημίσθαι</span>, «porque o rumor já se havia espalhado extensamente», AcPl Ha 4, 17s. e outros.</p><p class=\"entry-text\">② <strong>Marcador de culminação: agora, finalmente</strong>, na locução <span class=\"greek\">ἤδη</span> <span class=\"greek\">ποτέ</span> (Heráclito Estoico 62, p. 82, 14; Epicteto 3, 24, 9; Justino, D. 32, 5; 75, 2; óstraco de Tebas em Deissmann, LO 167 [LAE 186]), às vezes com tempo passado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:10</a>; 2Cl 13:1; outras vezes com futuro (Josefo, Ant. 3, 300): <span class=\"greek\">εἴ</span> <span class=\"greek\">πως</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">ποτὲ</span> <span class=\"greek\">εὐοδωθήσομαι</span> <span class=\"greek\">ἐλθεῖν</span>, «se, finalmente, porventura conseguirei ir», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:10</a>.</p><p class=\"entry-text\">③ <strong>Marcador de proximidade lógica e imediatismo: de fato</strong> (também em Atanásio): <span class=\"greek\">ἤδη</span> <span class=\"greek\">ἐμοίχευσεν</span>, «já adulterou», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a>; <span class=\"greek\">ἤδ</span>. <span class=\"greek\">κέκριται</span>, «já está julgado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:18</a>; <span class=\"greek\">ἤδ</span>. <span class=\"greek\">ἥττημα</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐστιν</span>, «já é derrota para vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:7</a>.</p><p class=\"entry-text\">④ <strong>Marcador de intensificação:</strong> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:28</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:7</a>, <span class=\"greek\">ἤδη</span> aproxima-se do sentido «realmente», ou da expressão coloquial «como se vê». — DELG; M-M; TW.</p></section></article>\n<article id=\"entry-hedion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥδιον, ἥδιστα</h1><div class=\"entry-meta\"><span>formas comparativa e superlativa remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">ἡδέως</span>.</p></section></article>\n<article id=\"entry-hedomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἥδομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἥσθην</span> (Justino, D. 142, 1; Atanásio 17, 2; cf. <span class=\"greek\">ἡδονή</span>, <span class=\"greek\">ἡδύς</span>; Homero e outros). <strong>Ter prazer em, deleitar-se com</strong>, com dativo <span class=\"greek\">τινί</span>, «algo» (Heródoto e outros; PGM 13, 657): <span class=\"greek\">τροφῇ</span> <span class=\"greek\">φθορᾶς</span>, «alimento perecível», IRo 7:3. — B. 1099; DELG; TW.</p></section></article>\n<article id=\"entry-hedone-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡδονή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete anterior; pré-socráticos, trágicos, Heródoto e outros).</p><p class=\"entry-text\">① <strong>Estado ou condição de experimentar prazer por qualquer motivo; prazer, deleite, fruição, agrado</strong> (Diodoro Sículo 3, 10, 2; Pv 17:1; Josefo, Ant. 3, 19; 4, 88). <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">ἡγεῖσθαί</span> <span class=\"greek\">τι</span>, «considerar algo um prazer», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2:13</a>; <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «algo dá prazer a alguém», 2Cl 15:5. Sobre o desejo de praticar o bem (Platão, Aristóteles; Josefo, C. Ap. 2, 189), Hs 6, 5, 7. Geralmente em sentido negativo: <strong>prazer [mau], desejo [ilícito]</strong> (Demóstenes 18, 138, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λοιδορίαις</span> <span class=\"greek\">ἡδ</span>., «prazer em injuriar»; Musônio 89, 16s., em oposição a <span class=\"greek\">ἀρετή</span>; frequentemente Fílon, Herm. Wr.; Atanásio 34, 1, <span class=\"greek\">πάσης</span> <span class=\"greek\">αἰσχρᾶς</span> <span class=\"greek\">ἡδονῆς</span>), mais plenamente <span class=\"greek\">ἡδ</span>. <span class=\"greek\">κακή</span>, ITr 6:2; IPhld 2:2. Em geral no plural (Vécio Valente 76, 1; 4Mc 5:23; 6:35; Justino, A I, 21, 5): <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span>, «prazeres da vida», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:14</a>; IRo 7:3. Em emprego absoluto, com <span class=\"greek\">ἐπιθυμίαι</span> (como Díon Crisóstomo 32 [49], 9; Élio Aristides 35, 27 K. = 9, p. 108 D.; 4Mc 5:23; Fílon, Agr. 83, 84 e outros; Melitão, P. 50, 361), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:3</a>; Dg 9:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 4:1</a>, 3; Dg 6:5; Hs 8, 8, 5; 8, 9, 4. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">ἐδέσμευεν</span>, «o Diabo prendeu a humanidade à sua concupiscência», AcPlCor 2:11.</p><p class=\"entry-text\">② <strong>Experiência sensorial prazerosa; sabor agradável</strong> (Sópater em Ateneu 14, 649a, <span class=\"greek\">ἡδ</span>. <span class=\"greek\">τραγημάτων</span> e outros; Nm 11:8; Sb 16:20; Josefo, Ant. 3, 28). <span class=\"greek\">ἡδονὴν</span> <span class=\"greek\">ἔχειν</span>, «ter sabor agradável», Hm 10, 3, 3; <span class=\"greek\">ἡδονὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴνου</span>, «sabor do vinho», Hm 12, 5, 3. — Renehan 1975, 100; DELG, s.v. <span class=\"greek\">ἥδομαι</span> A; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-heduosmon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἡδύοσμον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<span class=\"greek\">ἡδύς</span>, <span class=\"greek\">ὀσμή</span>; Teofrasto, HP 7, 7, 1; Estrabão 8, 3, 14; Dioscórides 3, 34; Galeno XI 882, 16 K.; XII 928, 9.) <strong>Hortelã</strong> (planta de jardim; Zohary, <em>Plants</em>, 88: erva perene <em>Mentha longifolia</em>, a espécie mais comum de hortelã). <span class=\"greek\">ἀποδεκατοῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἡδ</span>., «pagar o dízimo da hortelã», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:42</a> (com <span class=\"greek\">πήγανον</span>, como em Hippiatr. I, p. 12, 15). — DELG, s.v. <span class=\"greek\">ἥδομαι</span> B; M-M.</p></section></article>\n"};
